    SELECT
        v_owner,
        COALESCE(NULLIF(item.value->>'profile_id', '')::integer, 1),
        CASE
            WHEN jsonb_typeof(item.value->'collections_json') = 'array'
                THEN item.value->'collections_json'
            ELSE '[]'::jsonb
        END,
        COALESCE(NULLIF(item.value->>'created_at', '')::timestamptz, now()),
