    FROM jsonb_array_elements(COALESCE(v_data->'collections', '[]'::jsonb)) AS item(value)
    WHERE jsonb_typeof(item.value) = 'object';

    INSERT INTO public.profile_tracker_settings (
        user_id,
        profile_id,
        tracker,
        enabled_statuses,
        row_order,
        send_progress,
        updated_at
