    SELECT
        v_owner,
        COALESCE(NULLIF(item.value->>'profile_id', '')::integer, 1),
        NULLIF(item.value->>'tracker', ''),
        CASE
            WHEN jsonb_typeof(item.value->'enabled_statuses') = 'array'
                THEN ARRAY(SELECT jsonb_array_elements_text(item.value->'enabled_statuses'))
